<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import {api} from '../state';import {createLibraryApi,type LibraryGrant,type LibraryRef} from '../api/libraries';import {errorMessage} from '../api/errors';
const props=defineProps<{library:LibraryRef;initialUser?:{id:number;username:string}}>(),emit=defineEmits<{close:[];saved:[]}>(),client=createLibraryApi(api);
const grants=ref<LibraryGrant[]>([]),q=ref(''),page=ref(1),total=ref(0),users=ref<{id:number;username:string}[]>([]),loading=ref(false),saving=ref(false),error=ref('');let generation=0,closed=false;
const available=computed(()=>users.value.filter(user=>user.id!==props.library.owner_user_id&&!grants.value.some(grant=>grant.user_id===user.id)));
async function search(){const g=++generation;loading.value=true;error.value='';try{const data=await client.directory(q.value,page.value,20);if(closed||g!==generation)return;users.value=data.items;total.value=data.total}catch(e){if(g===generation)error.value=errorMessage(e)}finally{if(g===generation)loading.value=false}}
function add(user:{id:number;username:string}){if(user.id===props.library.owner_user_id||grants.value.some(grant=>grant.user_id===user.id))return;grants.value.push({user_id:user.id,username:user.username,permission:'read'})}
async function save(){saving.value=true;error.value='';try{await client.saveGrants(props.library.id,grants.value);emit('saved');emit('close')}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
onMounted(async()=>{try{grants.value=(await client.grants(props.library.id)).grants??[];if(props.initialUser)add(props.initialUser)}catch(e){error.value=errorMessage(e)}await search()});onBeforeUnmount(()=>{closed=true;generation++});
</script>
<template><div class="modal-backdrop" @click.self="!saving&&emit('close')"><section class="sheet grant-editor" role="dialog" aria-modal="true" aria-label="书库授权"><button class="close" :disabled="saving" @click="emit('close')">关闭</button><h2>「{{library.name}}」的授权</h2><p>所有者始终拥有管理权限。阅读可打开内容；贡献可导入；管理可维护该库和授权。</p><p v-if="error" role="alert" class="error">{{error}}</p><div v-for="grant in grants" :key="grant.user_id" class="grant-row"><strong>{{grant.username||'已授权成员'}}</strong><select v-model="grant.permission" :aria-label="(grant.username||'成员')+' 的库权限'" :disabled="saving"><option value="read">阅读</option><option value="contribute">贡献</option><option value="manage">管理</option></select><button :disabled="saving" @click="grants=grants.filter(item=>item.user_id!==grant.user_id)">移除授权</button></div><p v-if="!grants.length">尚未授权其他成员。</p><form class="toolbar" @submit.prevent="page=1;search()"><input v-model="q" aria-label="搜索授权成员" placeholder="输入用户名搜索"><button :disabled="loading||saving">搜索成员</button></form><p v-if="loading" role="status">正在搜索成员…</p><div v-for="user in available" :key="user.id" class="grant-row"><span>{{user.username}}</span><button :disabled="saving" @click="add(user)">添加授权</button></div><div v-if="total>20" class="pagination"><button :disabled="page===1||loading" @click="page--;search()">上一页</button><span>{{page}} / {{Math.ceil(total/20)}}</span><button :disabled="page*20>=total||loading" @click="page++;search()">下一页</button></div><div class="row-actions"><button class="primary" :disabled="saving" @click="save">{{saving?'保存中…':'保存授权'}}</button><button :disabled="saving" @click="emit('close')">取消</button></div></section></div></template>
<style scoped>.grant-editor{max-width:720px}.grant-row{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--border);padding:10px 0;min-width:0}.grant-row strong,.grant-row>span{flex:1;min-width:0;overflow-wrap:anywhere}.grant-row select{width:110px}.grant-row button{flex:none}.grant-editor p{font-size:13px;color:var(--muted)}@media(max-width:500px){.grant-row{flex-wrap:wrap}.grant-row strong{flex-basis:100%}.grant-row select{flex:1}}
</style>
